import sys

def find_min_number(d, s):
    if s == 0:
        return -1
    for n in range(1, 10**18 + 1):
        if n % d == 0 and sum(int(digit) for digit in str(n)) == s:
            return n
    return -1

def main():
    import sys
    input = sys.stdin.read().strip()
    d, s = map(int, input.split())
    result = find_min_number(d, s)
    print(result)

if __name__ == "__main__":
    main()
